contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        require(amt > 0);
        require(address(this).balance >= amt);
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(type(uint256).max); if (__ESBMC_reverted()) return;
        c.Deposit{value: amt}(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        bool reverted;
        c.Collect(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == balBefore);
    }
    receive() external payable {}
}

