// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt > 0);
        vm.assume(address(this).balance >= amt);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(type(uint256).max) {} catch { return; }
        try c.Deposit{value: amt}() {} catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.Collect(amt) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 amt) public {
        _run(amt);
    }

    receive() external payable {}
}
